import unicodedata
def normalize_text(text):
    text = str(text).lower().strip()

    text = unicodedata.normalize('NFD', text)
    text = text.encode('ascii', 'ignore').decode('utf-8')

    replacements = {
        "-": " ",
        "_": " ",
        "  ": " "
    }

    for k, v in replacements.items():
        text = text.replace(k, v)

    return text
